import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source implementing fp16 max‑pool 2d
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void maxpool2d_fp16_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    int N, int C,
    int H, int W,
    int outH, int outW,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * outH * outW;
    if (idx >= total) return;

    int w_out = idx % outW;
    int tmp   = idx / outW;
    int h_out = tmp % outH;
    tmp       = tmp / outH;
    int c     = tmp % C;
    int n     = tmp / C;

    int h_start = h_out * stride_h - pad_h;
    int w_start = w_out * stride_w - pad_w;

    half max_val = __float2half(-65504.0f); // smallest fp16

    for (int kh = 0; kh < kernel_h; ++kh) {
        int h_in = h_start + kh * dilation_h;
        if (h_in < 0 || h_in >= H) continue;
        for (int kw = 0; kw < kernel_w; ++kw) {
            int w_in = w_start + kw * dilation_w;
            if (w_in < 0 || w_in >= W) continue;
            int in_idx = ((n * C + c) * H + h_in) * W + w_in;
            half val = input[in_idx];
            max_val = __hgt(val, max_val) ? val : max_val;
        }
    }

    int out_idx = ((n * C + c) * outH + h_out) * outW + w_out;
    output[out_idx] = max_val;
}

torch::Tensor maxpool2d_fp16(
    torch::Tensor input,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w) {

    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    const int outH = (H + 2*pad_h - dilation_h*(kernel_h-1) - 1) / stride_h + 1;
    const int outW = (W + 2*pad_w - dilation_w*(kernel_w-1) - 1) / stride_w + 1;

    auto output = torch::empty({N, C, outH, outW}, input.options());

    const int threads = 256;
    const int total   = N * C * outH * outW;
    const int blocks  = (total + threads - 1) / threads;

    maxpool2d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const half*>(input.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        N, C, H, W,
        outH, outW,
        kernel_h, kernel_w,
        stride_h, stride_w,
        pad_h, pad_w,
        dilation_h, dilation_w);

    cudaDeviceSynchronize();
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("maxpool2d_fp16", &maxpool2d_fp16, "FP16 MaxPool2d forward (CUDA)");
}
'''

# Compile the CUDA kernel
maxpool2d_cuda = load_inline(
    name='maxpool2d_cuda',
    cpp_sources='',
    cuda_sources=cuda_src,
    functions=['maxpool2d_fp16'],
    verbose=False,
)

class MaxPool2dFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input,
                kernel_h, kernel_w,
                stride_h, stride_w,
                pad_h, pad_w,
                dilation_h, dilation_w):
        # input is expected to be fp16
        return maxpool2d_cuda.maxpool2d_fp16(
            input,
            kernel_h, kernel_w,
            stride_h, stride_w,
            pad_h, pad_w,
            dilation_h, dilation_w,
        )

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    All tensors are fp16.
    """
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super(ModelNew, self).__init__()
        self.kernel_h = self.kernel_w = kernel_size
        self.stride_h = self.stride_w = stride
        self.pad_h    = self.pad_w    = padding
        self.dilation_h = self.dilation_w = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16
        x_fp16 = x.to(torch.float16)
        out = MaxPool2dFunction.apply(
            x_fp16,
            self.kernel_h, self.kernel_w,
            self.stride_h, self.stride_w,
            self.pad_h, self.pad_w,
            self.dilation_h, self.dilation_w,
        )
        return out
